  ?z brick:hasSubClass* ?label .
  ?sensor brick:isPointOf ?z ;
          a brick:AirTemperatureSensor ;
          brick:hasPointName ?p .
  ?z rdf:type ?t .
  ?z brick:hasPointName ?point .
}

